import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { FALLBACK, readRoles, renderTheme, syncTheme } from "./theme.ts";

const SCHEMA = process.env.PI_THEME_SCHEMA
	?? join(process.env.HOME!, ".local/share/mise/installs/pi/latest/pi/theme/theme-schema.json");

const HEX = /^#[0-9a-f]{6}$/;

function tmp(): string {
	return mkdtempSync(join(tmpdir(), "ryoku-theme-"));
}

test("renders every colour role the Pi schema requires", () => {
	const schema = JSON.parse(readFileSync(SCHEMA, "utf8"));
	const theme = renderTheme(FALLBACK);
	for (const role of schema.properties.colors.required as string[]) {
		assert.ok(role in theme.colors, `missing role ${role}`);
	}
	assert.equal(theme.name, "ryoku");
});

test("every colour resolves to a concrete hex value through vars", () => {
	const theme = renderTheme(FALLBACK);
	const values = [...Object.values(theme.colors), ...Object.values(theme.export)];
	for (const value of values) {
		const resolved = HEX.test(value) ? value : theme.vars[value];
		assert.match(resolved ?? "", HEX, `unresolved ${value}`);
	}
});

test("maps roles the way the nvim Ryoku UI does", () => {
	const theme = renderTheme(FALLBACK);
	const colour = (role: string) => theme.vars[theme.colors[role]] ?? theme.colors[role];
	assert.equal(colour("text"), FALLBACK.onSurface);
	assert.equal(colour("border"), FALLBACK.outline);
	assert.equal(colour("borderMuted"), FALLBACK.outlineVariant);
	assert.equal(colour("syntaxKeyword"), FALLBACK.primary);
	assert.equal(colour("syntaxFunction"), FALLBACK.onSurface);
	assert.equal(colour("syntaxString"), FALLBACK.tertiary);
	assert.equal(colour("syntaxComment"), FALLBACK.outline);
	// error is the only chromatic role
	assert.equal(colour("error"), FALLBACK.error);
	assert.equal(colour("toolDiffRemoved"), FALLBACK.error);
	assert.equal(colour("userMessageBg"), FALLBACK.surfaceContainer);
});

test("appearance follows the surface lightness", () => {
	assert.equal(renderTheme(FALLBACK).appearance, "dark");
	const light = { ...FALLBACK, surface: "#fdf8f8", onSurface: "#1c1b1c" };
	assert.equal(renderTheme(light).appearance, "light");
});

test("readRoles drops alpha and falls back per missing role", () => {
	const dir = tmp();
	const file = join(dir, "colors.json");
	writeFileSync(file, JSON.stringify({ primary: "#AABBCCDD", surface: "not-a-colour" }));
	const roles = readRoles(file);
	assert.equal(roles.primary, "#aabbcc");
	assert.equal(roles.surface, FALLBACK.surface);
	assert.equal(roles.tertiary, FALLBACK.tertiary);
});

test("readRoles uses the fallback when the palette is missing or corrupt", () => {
	const dir = tmp();
	assert.deepEqual(readRoles(join(dir, "absent.json")), FALLBACK);
	const bad = join(dir, "bad.json");
	writeFileSync(bad, "{not json");
	assert.deepEqual(readRoles(bad), FALLBACK);
});

test("syncTheme writes the theme and reports no change on a second run", () => {
	const dir = tmp();
	const palette = join(dir, "colors.json");
	const out = join(dir, "themes", "ryoku.json");
	writeFileSync(palette, JSON.stringify({ ...FALLBACK, primary: "#123456" }));
	assert.equal(syncTheme(palette, out), true);
	const written = JSON.parse(readFileSync(out, "utf8"));
	assert.equal(written.vars.primary, "#123456");
	assert.equal(syncTheme(palette, out), false);
});

